arduino.globals:
#include <DHT.h>
#define DHTPIN_${COMP_SUFFIX} ${DATA}
#define DHTTYPE_${COMP_SUFFIX} DHT22
DHT dht_${COMP_SUFFIX}(DHTPIN_${COMP_SUFFIX}, DHTTYPE_${COMP_SUFFIX});

arduino.loop:
float humidity_${COMP_SUFFIX} = dht_${COMP_SUFFIX}.readHumidity();
float temperature_${COMP_SUFFIX} = dht_${COMP_SUFFIX}.readTemperature();
if (isnan(humidity_${COMP_SUFFIX}) || isnan(temperature_${COMP_SUFFIX})) {
  Serial.println("DHT22_${COMP_SUFFIX} read failed!");
} else {
  Serial.print("Humidity: ");
  Serial.print(humidity_${COMP_SUFFIX});
  Serial.print(" %  Temperature: ");
  Serial.print(temperature_${COMP_SUFFIX});
  Serial.println(" C");
}
delay(2000);
